package ru.kupiora.radar;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;
public class NotificationRoutingTest {
 @Test public void categoryCountsIgnoreReadAndOtherTopics()throws Exception{JSONArray a=new JSONArray().put(new JSONObject().put("categoryId","work").put("read",false)).put(new JSONObject().put("categoryId","health").put("read",false)).put(new JSONObject().put("categoryId","work").put("read",true));assertEquals(1,Inbox.unreadFor(a,"work"));assertEquals(1,Inbox.unreadFor(a,"health"));assertEquals(0,Inbox.unreadFor(a,"auto"));assertEquals(2,Inbox.unreadFor(a,""));}
 @Test public void readingWorkDoesNotChangeHealth()throws Exception{JSONArray a=new JSONArray().put(new JSONObject().put("id","work-1").put("categoryId","work").put("read",false)).put(new JSONObject().put("id","health-1").put("categoryId","health").put("read",false));JSONArray changed=Inbox.setRead(a,"work-1",true);assertEquals(0,Inbox.unreadFor(changed,"work"));assertEquals(1,Inbox.unreadFor(changed,"health"));assertEquals(1,Inbox.unreadFor(a,"work"));}
 @Test public void documentNoticeKeepsOfficialSourceAndStableIdentity()throws Exception{JSONObject act=new JSONObject().put("id","doc-12").put("title","Название").put("summary","Суть").put("categoryId","work").put("sourceUrl","https://publication.pravo.gov.ru/document/123");JSONObject notice=Inbox.documentNotice(act,1234);assertEquals("legal:doc-12",notice.getString("id"));assertEquals(act.getString("sourceUrl"),notice.getString("sourceUrl"));assertEquals(1234,notice.getLong("createdAt"));assertFalse(notice.getBoolean("read"));assertFalse(notice.getBoolean("test"));}
}
